
enum SameSite {
  strict = 'strict',
  lax = 'lax'
}

interface CookieAttributes{
  path?: string;
  domain?: string;
  expires?: string;
  maxAge?: number;
  secure?: boolean;
  sameSite?: SameSite;
}

function setCookie(key: string, value: string,{path = '/', domain, expires, maxAge = 60*60*14*30, secure, sameSite}: CookieAttributes = {} ): void {
  
  if(!key) return;

  value = encodeURIComponent(String(value)).replace(
    /%(23|24|26|2B|3A|3C|3E|3D|2F|3F|40|5B|5D|5E|60|7B|7D|7C)/g,
    decodeURIComponent
  );
  
  key = encodeURIComponent(String(key));
  key = key.replace(/%(23|24|26|2B|5E|60|7C)/g, decodeURIComponent);
  key = key.replace(/[()]/g, escape);

  const attrs: string[] = [];
  if(path) attrs.push(`path=${path}`); // path 非常重要, 默认是  location.pathname , 在删除或者修改 cookie 时候, path 没有对齐是无法修改 cookie 的.
  if(domain) attrs.push(`domain=${domain}`);
  if(expires) attrs.push(`expires=${expires}`);
  //! important:"max-age" is not supported by IE6/7/8
  if(maxAge) attrs.push(`max-age=${maxAge}`);
  if(secure)attrs.push('secure');
  if(sameSite)attrs.push(`samesite=${sameSite}`);
  document.cookie = `${key}=${value};${attrs.join(';')}`;
}

interface GetCookieOptions {
  json?: boolean;
}

function getCookie(key: string|undefined, options: GetCookieOptions={}): any {
  const COOKIE_SPLITTER = '; '
  const KEY_VALUE_SPLITTER = '=';  
  
  
  let result: any = key ? undefined : {};
  const cookies = document.cookie ? document.cookie.split(COOKIE_SPLITTER) : [];
  const REDCode = /(%[0-9A-Z]{2})+/g;

  for (let i = 0; i < cookies.length; i++) {
    const parts = cookies[i].split(KEY_VALUE_SPLITTER);
    let cookie = parts.slice(1).join(KEY_VALUE_SPLITTER);

    if (!options.json && cookie.charAt(0) === '"') {
      cookie = cookie.slice(1, -1);
    }

    try {
      const name = parts[0].replace(REDCode, decodeURIComponent);
      cookie = cookie.replace(REDCode, decodeURIComponent);

      if (options.json) {
        try {
          cookie = JSON.parse(cookie);
        } catch (e) {} // eslint-disable-line
      }

      if (key === name) {
        result = cookie;
        break;
      }

      if (!key) {
        result[name] = cookie;
      }
    } catch (e) {} // eslint-disable-line
  }
  return result;
}

function removeCookie(key: string, attrs: CookieAttributes={}): void {
  setCookie(
    key,
    '',
    Object.assign(attrs,{
      expires: 'Thu, 01 Jan 1970 00:00:00 GMT',
      maxAge: -1,
    })
  );
}

function getJSON(): {} {
  return getCookie( undefined ,{
    json: true,
  });
}

export {
  getCookie as get,
  setCookie as set,
  getJSON,
  removeCookie as remove
}

const Cookie = {
  set: setCookie,
  get: getCookie,
  getJSON,
  remove: removeCookie
}

export default Cookie;